import{_ as a,o as t,c as d,a3 as o}from"./chunks/framework.B8xISX-C.js";const h=JSON.parse('{"title":"weapons","description":"","frontmatter":{},"headers":[],"relativePath":"reference/weapons.md","filePath":"reference/weapons.md"}'),s={name:"reference/weapons.md"};function i(c,e,r,n,l,p){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="weapons" tabindex="-1">weapons <a class="header-anchor" href="#weapons" aria-label="Permalink to &quot;weapons&quot;">​</a></h1><p>A ship weapon. A beam is fully described by its record (damage pair, mods, space and cost). Missiles, torpedoes, fighters and special weapons also need rows in the combat rules.</p><p>A mod adds records in <code>records/weapons/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;weapons&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>weapons</code>. Schema: <code>schemas/records/weapons.schema.json</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-application" class="field-name"><code>application</code></span><a class="field-link" href="#f-application" aria-label="Link to application">#</a></td><td>key of a record in <code>applications</code>, or null</td><td>yes</td><td>the key of the application that unlocks it</td></tr><tr><td><span id="f-class" class="field-name"><code>class</code></span><a class="field-link" href="#f-class" aria-label="Link to class">#</a></td><td>one of <code>beam</code>, <code>missile</code>, <code>torpedo</code>, <code>bomb</code>, <code>fighter</code>, <code>special</code></td><td>yes</td><td></td></tr><tr><td><span id="f-ammo" class="field-name"><code>ammo</code></span><a class="field-link" href="#f-ammo" aria-label="Link to ammo">#</a></td><td>integer &gt;= 0 or null</td><td>yes</td><td></td></tr><tr><td><span id="f-space" class="field-name"><code>space</code></span><a class="field-link" href="#f-space" aria-label="Link to space">#</a></td><td>integer &gt;= 0</td><td>yes</td><td>ship space per mount</td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>integer &gt;= 0</td><td>yes</td><td>production cost per mount</td></tr><tr><td><span id="f-damage" class="field-name"><code>damage</code></span><a class="field-link" href="#f-damage" aria-label="Link to damage">#</a></td><td>[integer &gt;= 0, integer &gt;= 0]</td><td>yes</td><td>[minimum, maximum] damage in tactical combat</td></tr><tr><td><span id="f-strategicDamage" class="field-name"><code>strategicDamage</code></span><a class="field-link" href="#f-strategicDamage" aria-label="Link to strategicDamage">#</a></td><td>[integer &gt;= 0, integer &gt;= 0]</td><td>yes</td><td>[minimum, maximum] damage in strategic (auto-resolve) combat</td></tr><tr><td><span id="f-mods" class="field-name"><code>mods</code></span><a class="field-link" href="#f-mods" aria-label="Link to mods">#</a></td><td>list of snake_case key (no repeats)</td><td>yes</td><td>weapon-mod keys the weapon may carry</td></tr><tr><td><span id="f-inherentBits" class="field-name"><code>inherentBits</code></span><a class="field-link" href="#f-inherentBits" aria-label="Link to inherentBits">#</a></td><td>integer 0..65535</td><td>yes</td><td></td></tr><tr><td><span id="f-monster" class="field-name"><code>monster</code></span><a class="field-link" href="#f-monster" aria-label="Link to monster">#</a></td><td>true or false</td><td>yes</td><td>false for every player weapon</td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr></tbody></table><p>References to other records are written as keys; the game turns them into ids.</p><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>missile: combat-rules <code>fliers.missile.types</code> (append <code>{ weapon, hp, bd }</code>)</li><li>torpedo: combat-rules <code>fliers.torpedo.types</code></li><li>fighter: combat-rules <code>fliers.fighter.types</code> and ship-design <code>auto.fighters</code></li><li>special weapon: combat-rules <code>specialWeapons.weapons</code> with one of the existing <code>kind</code>s, and ship-design <code>auto.specialWeapons</code></li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>Beams: the ship designer picks the beam with the highest maximum damage, and the combat AI fires it by class. Missiles, torpedoes and fighters are used once their combat-rules and ship-design rows exist. A special weapon is used only through the existing kinds.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><code>class</code> is one of beam, missile, torpedo, bomb, fighter, special; no new classes.</li><li>New special weapon kinds need code.</li><li>Weapon mods (<code>mods</code>) come from the weapon-mods catalog, which is closed.</li><li>A missile, torpedo, fighter or special weapon without its combat-rules row is refused (<code>weapon-without-combat-row</code>).</li><li>The design screens show <code>&lt;nameKey&gt;</code> with <code>.name</code> replaced by <code>.plural</code> and <code>.note</code>: the mod&#39;s English text needs both. The <code>.note</code> has room for about 35 characters in the weapon list; a longer note is cut off with an ellipsis.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>ammo</code>, <code>application</code>, <code>class</code>, <code>cost</code>, <code>damage</code>, <code>inherentBits</code>, <code>mods</code>, <code>monster</code>, <code>nameKey</code>, <code>space</code>, <code>strategicDamage</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: <code>mods</code></li></ul>',16)])])}const f=a(s,[["render",i]]);export{h as __pageData,f as default};
